'use client'

/**
 * IMPORTANT: This component was built for demo purposes only and has not been tested in production.
 * It serves as a proof of concept for a checkbox tree implementation.
 * If you're interested in collaborating to create a more robust, production-ready
 * headless component, your contributions are welcome!
 */

'use client'

import React, { useCallback, useMemo, useState } from 'react'

interface TreeNode {
  id: string
  label: string
  defaultChecked?: boolean
  children?: TreeNode[]
}

function useCheckboxTree(initialTree: TreeNode) {
  const initialCheckedNodes = useMemo(() => {
    const checkedSet = new Set<string>()
    const initializeCheckedNodes = (node: TreeNode) => {
      if (node.defaultChecked) {
        checkedSet.add(node.id)
      }
      node.children?.forEach(initializeCheckedNodes)
    }
    initializeCheckedNodes(initialTree)
    return checkedSet
  }, [initialTree])

  const [checkedNodes, setCheckedNodes] = useState<Set<string>>(initialCheckedNodes)

  const isChecked = useCallback(
    (node: TreeNode): boolean | 'indeterminate' => {
      if (!node.children) {
        return checkedNodes.has(node.id)
      }

      const childrenChecked = node.children.map((child) => isChecked(child))
      if (childrenChecked.every((status) => status === true)) {
        return true
      }
      if (childrenChecked.some((status) => status === true || status === 'indeterminate')) {
        return 'indeterminate'
      }
      return false
    },
    [checkedNodes]
  )

  const handleCheck = useCallback(
    (node: TreeNode) => {
      const newCheckedNodes = new Set(checkedNodes)

      const toggleNode = (n: TreeNode, check: boolean) => {
        if (check) {
          newCheckedNodes.add(n.id)
        } else {
          newCheckedNodes.delete(n.id)
        }
        n.children?.forEach((child) => toggleNode(child, check))
      }

      const currentStatus = isChecked(node)
      const newCheck = currentStatus !== true

      toggleNode(node, newCheck)
      setCheckedNodes(newCheckedNodes)
    },
    [checkedNodes, isChecked]
  )

  return { isChecked, handleCheck }
}

interface CheckboxTreeProps {
  tree: TreeNode
  renderNode: (props: {
    node: TreeNode
    isChecked: boolean | 'indeterminate'
    onCheckedChange: () => void
    children: React.ReactNode
  }) => React.ReactNode
}

export function CheckboxTree({ tree, renderNode }: CheckboxTreeProps) {
  const { isChecked, handleCheck } = useCheckboxTree(tree)

  const renderTreeNode = (node: TreeNode): React.ReactNode => {
    const children = node.children?.map(renderTreeNode)

    return renderNode({
      node,
      isChecked: isChecked(node),
      onCheckedChange: () => handleCheck(node),
      children,
    })
  }

  return renderTreeNode(tree)
}

.checkbox-tree {
  display: flex;
  flex-direction: column;
  gap: 12rpx;
}

.checkbox-tree-item {
  display: flex;
  align-items: center;
  gap: 12rpx;
}

.checkbox-tree-label {
  font-size: 28rpx;
  color: #111827;
}

type CheckboxTreeNode = {
  id: string
  label: string
  checked?: boolean
  disabled?: boolean
  children?: CheckboxTreeNode[]
}

type FlatNode = CheckboxTreeNode & { level: number }

const flattenNodes = (nodes: CheckboxTreeNode[], level = 0, acc: FlatNode[] = []) => {
  nodes.forEach((node) => {
    acc.push({
      ...node,
      level,
    })
    if (Array.isArray(node.children) && node.children.length > 0) {
      flattenNodes(node.children, level + 1, acc)
    }
  })
  return acc
}

Component({
  options: {
    styleIsolation: 'apply-shared',
  },

  properties: {
    nodes: {
      type: Array,
      value: [],
    },
    checkedKeys: {
      type: Array,
      value: [],
    },
    extClass: {
      type: String,
      value: '',
    },
  },

  data: {
    flatNodes: [] as FlatNode[],
    checkedMap: {} as Record<string, boolean>,
  },

  lifetimes: {
    attached() {
      this.syncFromProps()
    },
  },

  observers: {
    'nodes, checkedKeys': function () {
      this.syncFromProps()
    },
  },

  methods: {
    syncFromProps() {
      const flatNodes = flattenNodes((this.properties.nodes || []) as CheckboxTreeNode[])
      const checkedMap: Record<string, boolean> = {}
      ;(this.properties.checkedKeys as string[]).forEach((id) => {
        checkedMap[id] = true
      })
      flatNodes.forEach((node) => {
        if (node.checked && checkedMap[node.id] === undefined) {
          checkedMap[node.id] = true
        }
      })
      this.setData({ flatNodes, checkedMap })
    },

    onToggle(e: WechatMiniprogram.BaseEvent) {
      const id = e.currentTarget.dataset.id as string
      if (!id) return
      const checkedMap = { ...(this.data.checkedMap || {}) }
      checkedMap[id] = !checkedMap[id]
      const checkedKeys = Object.keys(checkedMap).filter((key) => checkedMap[key])
      this.setData({ checkedMap })
      this.triggerEvent('change', {
        checkedKeys,
      })
      this.triggerEvent('update:checkedKeys', checkedKeys)
    },
  },
})
